  function renderAdminScopeSwitcher(role=workspaceRole){const host=$('adminScopeSwitcher');if(!host)return;host.replaceChildren();if(!(isBizWorkspace||adminHubSource==='ekodibiz')||!hasFullWorkspaceAdminScope(role)||!adminHubScopes.length){host.hidden=true;return}host.hidden=false;const label=document.createElement('span');label.className='admin-scope-label';label.textContent='관리 영역';host.append(label);const current=service==='mall'?'mall':workspace==='ekodi-lab'?'lab':'common';for(const scope of adminHubScopes){const a=document.createElement('a');a.href=scope.adminHref;a.textContent=scope.label;a.dataset.adminScope=scope.id;a.title=scope.description||scope.label;if(scope.id===current){a.classList.add('active');a.setAttribute('aria-current','page')}host.append(a)}}
  const canSection=(key,role=workspaceRole)=>{const capability=SECTION_CAPABILITY[key];const allowed=roleCapabilities(role);return Boolean(capability&&(allowed.includes('*')||allowed.includes(capability)));};
  function groupForSection(key){return navGroups.find(group=>group.sections.some(([sectionKey])=>sectionKey===key))?.id||navGroups[0]?.id||''}function visibleGroupSections(group,role){if(!group||!role)return[];return group.sections.filter(([key])=>canSection(key,role))}function renderSecondaryNav(groupId,role=workspaceRole){const h=$('sectionNav');if(!h)return;h.replaceChildren();const group=navGroups.find(item=>item.id===groupId)||navGroups[0];if(!role){const lock=document.createElement('span');lock.className='admin-subnav-lock';lock.textContent='로그인 후 세부 메뉴가 표시됩니다.';h.append(lock);return}const sections=visibleGroupSections(group,role);if(!sections.length){const empty=document.createElement('span');empty.className='admin-subnav-lock';empty.textContent='현재 권한에서 사용할 수 있는 세부 메뉴가 없습니다.';h.append(empty);return}for(const [key,label] of sections){const a=document.createElement('a');a.href=key==='overview'?adminBase:`${adminBase}/${key}`;a.textContent=label;if(key===section)a.classList.add('active');h.append(a)}}function renderNav(role=workspaceRole){const h=$('adminNav');h.replaceChildren();const allowedGroups=navGroups.filter(group=>!role||visibleGroupSections(group,role).length);if(!selectedNavGroup||!allowedGroups.some(group=>group.id===selectedNavGroup))selectedNavGroup=allowedGroups.find(group=>group.id===groupForSection(section))?.id||allowedGroups[0]?.id||'';for(const group of allowedGroups){const button=document.createElement('button');button.type='button';button.dataset.adminGroup=group.id;button.textContent=group.label;if(group.id===selectedNavGroup)button.classList.add('active');button.addEventListener('click',()=>{selectedNavGroup=group.id;for(const node of h.querySelectorAll('[data-admin-group]'))node.classList.toggle('active',node.dataset.adminGroup===group.id);renderSecondaryNav(group.id,role)});h.append(button)}renderSecondaryNav(selectedNavGroup,role)}
  function publishTenantContext(){if(!workspaceContext)return;document.documentElement.dataset.ekodiTenant=workspaceContext.slug;document.documentElement.dataset.ekodiTenantRole=workspaceRole;document.documentElement.dataset.ekodiAuthorityScope='tenant';document.documentElement.dataset.ekodiAdminSection=section;const detail={tenantId:workspaceContext.tenantId,workspaceKey:workspaceContext.workspaceKey||`tenant:${workspaceContext.tenantId}`,workspaceName:workspaceContext.name||workspaceLabel(),role:workspaceRole,authorityScope:'tenant',surface:'admin',service:service||'space',capabilities:roleCapabilities(workspaceRole)};window.dispatchEvent(new CustomEvent('ekodi:tenant-context',{detail}));window.dispatchEvent(new CustomEvent('ekodi:context-change',{detail}));window.EKODIAdminUIShell?.refresh?.()}
  function applyWorkspaceContext(context){workspaceContext=context;workspaceRole=String(context?.role||'').trim().toLowerCase();selectedNavGroup=groupForSection(section);renderNav(workspaceRole);renderAdminScopeSwitcher(workspaceRole);publishTenantContext()}
  function canonicalSubjectKey(){if(service==='mall')return 'ekodimall';return String(workspaceContext?.slug||(workspace==='ekodibiz'?'ekodi-biz':workspace==='ekodi-trade'?'ekoditrade':workspace)).trim().toLowerCase()}
  function channelTargetAccount(provider){const key=`${canonicalSubjectKey()}:${service||'space'}:${String(provider||'').toLowerCase()}`;return CHANNEL_TARGET_ACCOUNTS[key]||''}

  function languageServiceId(){if(service==='mall')return'mall';return({'cgma':'cgma','cheonggye':'cgma','ekodibiz':'biz','ekodi-biz':'biz','ekodi-church':'church','ekodi-lab':'lab','ekodi-trade':'trade'})[workspace]||workspace.replace(/^ekodi-/,'')}
  async function languageApi(path='',options={}){const token=await accessToken();if(!token)throw Object.assign(new Error('AUTH_REQUIRED'),{status:401});const id=languageServiceId();const join=path.includes('?')?'&':'?';const url=LANGUAGE_API+path+join+'service='+encodeURIComponent(id);const r=await fetch(url,{...options,headers:{authorization:`Bearer ${token}`,'content-type':'application/json',...(options.headers||{})},cache:'no-store'});const d=await r.json().catch(()=>({}));if(!r.ok)throw Object.assign(new Error(d.error||`language_${r.status}`),{status:r.status});return d}
  function languageStatusLabel(item){return item.status==='source'?'원문':item.status==='published'?'번역완료':item.status==='release-ready'?'게시준비':item.status==='validating'?'검증중':item.status==='translating'?'번역중':item.status==='stale'?'원문변경':'대기'}
  async function languageAdmin(){try{state('다국어 상태 확인 중');const data=await languageApi('/status');const site=data.site||{},rows=Array.isArray(site.languages)?site.languages:[];const published=rows.filter(x=>x.public).length,ready=rows.filter(x=>['source','published'].includes(x.status)).length;$('summaryCards').innerHTML=[card('사이트',site.name||workspaceLabel(),'site scoped'),card('게시 언어',String(published),rows.filter(x=>x.public).map(x=>x.label).join(' · ')||'한국어'),card('번역완료',String(ready),rows.length+'개 등록'),card('권한',data.authority?.role||workspaceRole,'같은 중앙 원장')].join('');const body=rows.map(item=>{const source=item.locale==='ko-KR'||item.status==='source',ready=['source','published'].includes(item.status),next=item.public?'hidden':'published',disabled=source||!ready;return `<div class="service-row"><div><strong>${ae(item.label||item.locale)} · ${ae(item.locale)}</strong><p>번역 ${ae(languageStatusLabel(item))} · 게시 ${item.public?'ON':'OFF'}</p></div><button class="button ${item.public?'':'primary'}" type="button" data-language-toggle="${ae(item.locale)}" data-next="${next}" ${disabled?'disabled':''}>${source?'기본 공개':item.public?'게시 중지':ready?'게시':'번역 준비 중'}</button></div>`}).join('');$('mainPanel').innerHTML=`<h2>다국어 번역·게시</h2><p class="empty">이 사이트의 번역 상태와 게시 여부만 관리합니다. 최고관리자 화면과 같은 중앙 원장을 사용하므로 어느 쪽에서 변경해도 즉시 연동됩니다.</p><div class="service-list">${body}</div><p class="empty">원문이 바뀌면 기존 번역은 자동으로 비게시되어 검증 전 혼합 언어 노출을 막습니다.</p>`;document.querySelectorAll('[data-language-toggle]').forEach(btn=>btn.onclick=async()=>{btn.disabled=true;state('게시 상태 변경 중');try{await languageApi('/publication',{method:'PUT',body:JSON.stringify({locale:btn.dataset.languageToggle,publicationStatus:btn.dataset.next})});await languageAdmin()}catch(e){state('변경 실패');$('pageCopy').textContent=e.message;btn.disabled=false}});state('다국어 관리')}catch(e){if(e.status===401)return loginPanel();$('summaryCards').innerHTML=[card('다국어','확인 필요','권한 또는 연결 확인')].join('');$('mainPanel').innerHTML=`<h2>다국어 번역·게시</h2><p class="empty">${ae(e.message)}</p>`;state('확인 필요')}}

  function card(label,value,small=''){return `<article class="card"><span>${label}</span><strong>${value}</strong><small>${small}</small></article>`}
