  function storedSession(){try{const v=JSON.parse(sessionStorage.getItem(SESSION_KEY)||'null');return v?.accessToken?v:null}catch{return null}}
  function saveSession(v){sessionStorage.setItem(SESSION_KEY,JSON.stringify(v))}
  function clearSession(){sessionStorage.removeItem(SESSION_KEY)}
  function designAuthUrl(){const u=new URL(AUTH_URL);u.searchParams.set('site','space');u.searchParams.set('return_to',location.origin+location.pathname+location.search);return u.href}
  function authUrl(){const u=new URL(AUTH_URL);u.searchParams.set('site','mail');u.searchParams.set('return_to',location.origin+location.pathname+location.search);return u.href}
  async function supabaseAuth(path,body){const r=await fetch(SUPABASE_URL+path,{method:'POST',headers:{apikey:SUPABASE_KEY,'content-type':'application/json'},body:JSON.stringify(body)});const d=await r.json().catch(()=>({}));if(!r.ok)throw Object.assign(new Error(d.msg||d.error_description||d.error||`auth_${r.status}`),{status:r.status});return d}
  function normalizeAuthSession(d,current={}){return{accessToken:d.access_token||'',refreshToken:d.refresh_token||current.refreshToken||'',expiresIn:Number(d.expires_in||3600),expiresAt:Number(d.expires_at||0)||Math.floor(Date.now()/1000)+Number(d.expires_in||3600),user:{id:d.user?.id||current.user?.id||'',email:d.user?.email||current.user?.email||''}}}
  async function exchangeCentralToken(){const p=new URLSearchParams(location.hash.slice(1));const tokenHash=p.get('ekodi_token');if(!tokenHash)return storedSession();const d=await supabaseAuth('/auth/v1/verify',{token_hash:tokenHash,type:p.get('ekodi_type')||'email'});const session=normalizeAuthSession(d);if(!session.accessToken)throw new Error('로그인 연결에 실패했습니다.');saveSession(session);history.replaceState(null,'',location.pathname+location.search);return session}
  async function accessToken(){let s=storedSession();if(!s?.accessToken)return'';const now=Math.floor(Date.now()/1000);if(!s.expiresAt||Number(s.expiresAt)>now+60)return s.accessToken;if(!s.refreshToken){clearSession();return''}try{const d=await supabaseAuth('/auth/v1/token?grant_type=refresh_token',{refresh_token:s.refreshToken});const session=normalizeAuthSession(d,s);if(!session.accessToken){clearSession();return''}saveSession(session);return session.accessToken}catch{clearSession();return''}}
  function workspaceSlugs(){if(service==='mall')return new Set(['ekodimall']);const values=new Set([workspace]);if(workspace==='ekodibiz')values.add('ekodi-biz');if(workspace==='ekodi-biz')values.add('ekodibiz');if(workspace==='ekodi-trade')values.add('ekoditrade');if(workspace==='ekoditrade')values.add('ekodi-trade');if(workspace==='cgma')values.add('cheonggye');if(workspace==='cheonggye')values.add('cgma');return values}
  async function loadWorkspaceContext(){const token=await accessToken();if(!token)return null;const r=await fetch(`${SUPABASE_URL}/rest/v1/rpc/current_site_activity_contexts`,{method:'POST',headers:{apikey:SUPABASE_KEY,authorization:`Bearer ${token}`,'content-type':'application/json'},body:'{}',cache:'no-store'});const rows=await r.json().catch(()=>[]);if(!r.ok)throw Object.assign(new Error(rows?.message||rows?.error||`context_${r.status}`),{status:r.status});const slugs=workspaceSlugs();const item=(Array.isArray(rows)?rows:[]).find(row=>slugs.has(String(row?.tenant||'').trim().toLowerCase()));if(!item?.tenant_id)return null;return{tenantId:String(item.tenant_id),workspaceKey:String(item.workspace_key||''),slug:String(item.tenant||workspace).trim().toLowerCase(),name:String(item.workspace_name||workspaceLabel()),kind:String(item.workspace_kind||'organization'),role:String(item.authorization_role||'').trim().toLowerCase()}}
  function workspaceAuthUrl(){const u=new URL(AUTH_URL);u.searchParams.set('site',workspace==='cgma'?'cgma':'space');u.searchParams.set('return_to',location.origin+location.pathname+location.search);u.searchParams.set('direct','1');if(service==='mall'||workspace==='ekodibiz'||workspace==='ekodi-biz'){u.searchParams.set('expected_account','topmaster.joseph@gmail.com');u.searchParams.set('force_account','1')}return u.href}
  function saveChannelIntent(provider){if(!CHANNEL_PROVIDERS[provider])return false;sessionStorage.setItem(CHANNEL_INTENT_KEY,JSON.stringify({provider,workspace,service,section,createdAt:Date.now()}));return true}
  function clearChannelIntent(){sessionStorage.removeItem(CHANNEL_INTENT_KEY)}
  function pendingChannelIntent(){try{const intent=JSON.parse(sessionStorage.getItem(CHANNEL_INTENT_KEY)||'null');if(!intent||!CHANNEL_PROVIDERS[intent.provider]||intent.workspace!==workspace||intent.service!==service||intent.section!=='channels'||Date.now()-Number(intent.createdAt||0)>CHANNEL_INTENT_MAX_AGE_MS){clearChannelIntent();return''}return intent.provider}catch{clearChannelIntent();return''}}
  async function channelPreAuth(){let platform={},healthKnown=false;try{const h=await growth('/health');platform=h.platform||{};healthKnown=true}catch{}const ready=provider=>!healthKnown||Boolean(platform[CHANNEL_PROVIDERS[provider].healthKey]);const button=(provider)=>{const item=CHANNEL_PROVIDERS[provider],enabled=ready(provider);return `<button class="button ${enabled?'primary':''}" type="button" data-channel-preauth="${provider}" ${enabled?'':'disabled'}>${item.label} 선택${enabled?` · ${item.login} 연결`: ' · 설정 대기'}</button>`};$('summaryCards').innerHTML=[card('1','채널 선택','Google 로그인보다 먼저'),card('2','운영공간 본인확인','EKODI 관리자 권한'),card('3','채널 권한 승인','선택한 제공자만 연결')].join('');$('mainPanel').innerHTML=`<h2>연결할 게시 채널을 먼저 선택하세요</h2><p class="empty">채널을 고르기 전에는 Google·Meta·Threads 로그인 화면을 열지 않습니다. 선택 후 운영공간 권한을 확인하고, 그 다음 선택한 채널의 공식 승인 화면으로 이어집니다.</p><div class="actions">${button('youtube')}${button('meta')}${button('threads')}</div><p class="empty" style="margin-top:16px">YouTube 연결 대상 계정: <strong>${ae(channelTargetAccount('youtube')||'인증 시 Google 계정 선택')}</strong></p><p class="empty" style="margin-top:16px">이 화면에서는 연결 상태나 계정 데이터가 공개되지 않습니다. 실제 상태 확인과 설정 변경은 운영공간 로그인 뒤에만 가능합니다.</p>`;document.querySelectorAll('[data-channel-preauth]').forEach(btn=>btn.onclick=()=>{const provider=btn.dataset.channelPreauth;if(!saveChannelIntent(provider))return;state(`${CHANNEL_PROVIDERS[provider].label} 선택됨 · 관리자 본인확인`);location.assign(workspaceAuthUrl())});state('채널 선택')}
  function loginPanel(message='운영공간 관리에는 권한 있는 계정 로그인이 필요합니다.'){$('summaryCards').replaceChildren();const channelLink=service==='mall'?`<a class="button" href="${adminBase}/channels">게시 채널 먼저 선택</a>`:'';$('mainPanel').innerHTML=`<h2>운영공간 로그인</h2><p class="empty">${message}</p><div class="actions"><a class="button primary" href="${workspaceAuthUrl()}">Google 계정으로 계속</a>${channelLink}<a class="button" href="${workspacePublicUrl()}">사용자 화면</a></div>`;state('로그인 필요')}
  function deniedPanel(){$('summaryCards').innerHTML=[card('운영공간',workspaceLabel(),'tenant isolated'),card('접근','차단','운영 권한 필요')].join('');$('mainPanel').innerHTML='<h2>권한이 없습니다</h2><p class="empty">현재 계정에는 이 운영공간의 관리자 권한이 없습니다. 플랫폼 권한만으로 고객 데이터에 자동 진입하지 않습니다.</p>';state('접근 차단')}
