  async function mailApi(path,options={}){const token=await accessToken();if(!token)throw Object.assign(new Error('AUTH_REQUIRED'),{code:'AUTH_REQUIRED'});const r=await fetch(MAIL_CONTROL+path,{...options,headers:{'content-type':'application/json',authorization:`Bearer ${token}`,...(options.headers||{})},cache:'no-store'});const d=await r.json().catch(()=>({}));if(r.status===401||r.status===403){if(r.status===401)clearSession()}if(!r.ok)throw Object.assign(new Error(d.error||`메일 요청 실패 (${r.status})`),{code:d.code||'MAIL_ERROR',status:r.status});return d}
