  function designForm(profile={}){const opt=(v,label,current)=>`<option value="${v}" ${current===v?'selected':''}>${label}</option>`;return `<form id="designForm"><div class="design-grid"><div class="design-field"><strong>설정 방식</strong><select name="mode">${opt('baseline','공통 기본값',profile.mode)}${opt('manual','직접 선택',profile.mode)}${opt('recommended','AI 추천',profile.mode)}</select></div><div class="design-field"><strong>색상 톤</strong><select name="tone">${opt('inherit','사이트 기본',profile.tone)}${opt('warm','따뜻함',profile.tone)}${opt('calm','차분함',profile.tone)}${opt('vivid','생동감',profile.tone)}${opt('mono','모노톤',profile.tone)}${opt('night','나이트',profile.tone)}</select></div><div class="design-field"><strong>에코디언 캐릭터</strong><select name="character">${opt('auto','사이트 맞춤 자동',profile.character)}${opt('off','사용 안 함',profile.character)}${opt('welcome','환영형',profile.character)}${opt('guide','안내형',profile.character)}${opt('read','읽기형',profile.character)}${opt('idea','아이디어형',profile.character)}</select></div><div class="design-field"><strong>계절 분위기</strong><select name="season">${opt('auto','계절 자동',profile.season)}${opt('off','사용 안 함',profile.season)}${opt('spring','봄',profile.season)}${opt('summer','여름',profile.season)}${opt('autumn','가을',profile.season)}${opt('winter','겨울',profile.season)}</select></div><div class="design-field"><strong>움직임</strong><select name="motion">${opt('inherit','사이트 기본',profile.motion)}${opt('still','정적',profile.motion)}${opt('gentle','부드럽게',profile.motion)}</select></div><div class="design-field"><strong>푸터</strong><select name="footer">${opt('contextual','공통엔진 + 사이트 맥락',profile.footer)}${opt('inherit','공통 기본',profile.footer)}</select></div></div><div class="design-preview"><div class="design-swatch"></div><div><strong>미리보기 원칙</strong><p class="design-note">레이아웃·접근성·헤더·푸터 같은 큰 틀은 공통엔진이 유지합니다. 여기서는 승인된 선택사항만 바뀝니다.</p></div></div><div class="actions"><button class="button primary" type="submit">설정 저장</button><button class="button" type="button" id="applyAiDesign">AI 추천 불러오기</button><a class="button" href="${workspacePublicUrl()}" target="_blank" rel="noopener">사용자 화면 보기</a></div></form>`;}
  async function designAdmin(){try{await exchangeCentralToken();if(!(await accessToken())){location.assign(designAuthUrl());return}state('설정 확인 중');const data=await designApi();$('summaryCards').innerHTML=[card('공통엔진','Adaptive Design v1','큰 틀 고정'),card('선택모드',data.profile?.mode||'baseline','관리자 선택'),card('캐릭터',data.profile?.character||'auto','승인된 유형'),card('계절',data.profile?.season||'auto','얇은 시각 레이어')].join('');$('mainPanel').innerHTML='<h2>사이트 스타일</h2><p class="empty">공통엔진의 안정성을 유지하면서 이 사이트의 표정만 선택합니다.</p>'+designForm(data.profile||{});const form=$('designForm');form.onsubmit=async e=>{e.preventDefault();state('저장 중');const payload=Object.fromEntries(new FormData(form).entries());try{await designApi('',{method:'PUT',body:JSON.stringify({profile:payload})});state('저장됨');await designAdmin()}catch(err){state('저장 실패');$('pageCopy').textContent=err.message}};$('applyAiDesign').onclick=async()=>{state('AI 추천 계산 중');try{const rec=await designApi('/recommend',{method:'POST',body:'{}'});$('mainPanel').innerHTML='<h2>AI 추천 설정</h2><p class="empty">사이트 성격과 공통 디자인 정책을 기준으로 추천했습니다. 저장 전 수정할 수 있습니다.</p>'+designForm(rec.profile||{});const f=$('designForm');f.onsubmit=async e=>{e.preventDefault();const payload=Object.fromEntries(new FormData(f).entries());payload.mode='recommended';await designApi('',{method:'PUT',body:JSON.stringify({profile:payload})});await designAdmin()};$('applyAiDesign').onclick=()=>designAdmin();state('추천 준비됨')}catch(err){state('추천 실패');$('pageCopy').textContent=err.message}};state('관리 가능')}catch(e){if(e.status===401){location.assign(designAuthUrl());return}$('mainPanel').innerHTML=`<h2>사이트 스타일</h2><p class="empty">${e.message}</p>`;state('확인 필요')}}
  async function events(){const q=new URLSearchParams({select:'id,event_type,campaign,source,medium,content,target_host,test,created_at',order:'created_at.desc',limit:'200'});const r=await fetch(`${SUPABASE_URL}/rest/v1/mall_sales_events?${q}`,{headers:{apikey:SUPABASE_KEY,authorization:`Bearer ${SUPABASE_KEY}`},cache:'no-store'});if(!r.ok)throw new Error(`ledger_${r.status}`);return r.json()}
  function stats(list){const real=list.filter(x=>!x.test);const n=t=>real.filter(x=>x.event_type===t).length;return{real,visits:n('mall_visit'),views:n('product_view'),clicks:n('affiliate_click'),conversions:n('conversion')}}
  function ledger(list){const s=stats(list);$('summaryCards').innerHTML=[card('실제 유입',fmt(s.visits),'test 제외'),card('상품조회',fmt(s.views),'실제 이벤트'),card('제휴클릭',fmt(s.clicks),'실제 이벤트'),card('전환',fmt(s.conversions),'기록된 전환')].join('');const rows=s.real.slice(0,100).map(e=>`<tr><td>${new Date(e.created_at).toLocaleString('ko-KR')}</td><td><span class="tag">${e.event_type||'-'}</span></td><td>${e.source||'-'}</td><td>${e.campaign||'-'}</td><td>${e.content||'-'}</td><td>${e.target_host||'-'}</td></tr>`).join('');$('mainPanel').innerHTML=`<h2>최근 실제 영업 이벤트</h2>${rows?`<div class="table-wrap"><table><thead><tr><th>시각</th><th>이벤트</th><th>채널</th><th>캠페인</th><th>콘텐츠</th><th>대상</th></tr></thead><tbody>${rows}</tbody></table></div>`:'<p class="empty">실제 이벤트가 아직 없습니다.</p>'}`;state('실데이터')}
  async function growth(path='/health',options={}){const token=await accessToken();const join=path.includes('?')?'&':'?';const scoped=path.startsWith('/v1/')?`${path}${join}subject_type=tenant&subject_key=${encodeURIComponent(canonicalSubjectKey())}`:path;const headers={'content-type':'application/json',...(options.headers||{})};if(token)headers.authorization=`Bearer ${token}`;const r=await fetch(GROWTH_API+scoped,{...options,headers,cache:'no-store'});const d=await r.json().catch(()=>({}));if(!r.ok)throw Object.assign(new Error(d.error||`채널 요청 실패 (${r.status})`),{status:r.status,code:d.error});return d}
  async function yt(){try{const h=await growth('/health');return{ok:h.ok,canUpload:Boolean(h.platform?.youtubeConfigured),oauthClientConfigured:Boolean(h.platform?.youtubeConfigured),refreshTokenStored:false,reason:h.platform?.youtubeConfigured?'OAuth broker ready':'Google OAuth 중앙 설정 필요',platform:h.platform||{}}}catch{return{ok:false,canUpload:false,reason:'NETWORK_ERROR',platform:{}}}}
  function rootHome(){const name=workspaceLabel();const isBiz=workspace==='ekodi-biz'||workspace==='ekodibiz';$('summaryCards').innerHTML=[card('운영공간',name,'tenant scoped'),card('내 권한',workspaceRole||'-','Capability 기준'),card('공통 Shell','Admin Shell v2','권한에 따라 투영'),card('관리경로','/admin','공간 하위')].join('');const rows=[];if(workspace==='cgma'&&canSection('member'))rows.push(`<div class="service-row"><div><strong>정회원</strong><p>청계면상인회 소속 정회원 원본 Sheet 관리</p></div><a href="${adminBase}/member">관리</a></div>`);if(canSection('mail'))rows.push(`<div class="service-row"><div><strong>메일</strong><p>고유 도메인 주소 · Gmail 전달 · DNS 인증</p></div><a href="${adminBase}/mail">관리</a></div>`);if(isBiz&&canSection('mall'))rows.push(`<div class="service-row"><div><strong>에코디몰</strong><p>상품·홍보·유입·제휴 영업 관리</p></div><a href="${base}/mall/admin">열기</a></div>`);if(isBiz&&canSection('work')){rows.push('<div class="service-row"><div><strong>Business OS</strong><p>에코디비즈 경영 운영</p></div><a href="https://ekodi.kr/business/ekodibiz">열기</a></div>');rows.push(`<div class="service-row"><div><strong>무역거래</strong><p>상대회사·담당자·회사별 관리자 권한</p></div><a href="${base}/trade/admin">열기</a></div>`)}$('mainPanel').innerHTML='<h2>허용된 서비스</h2><div class="service-list">'+(rows.join('')||'<p class="empty">현재 역할에서 사용할 수 있는 추가 서비스가 없습니다.</p>')+'</div>';state('운영공간')}
  function loginMailPanel(message='메일 관리에는 운영공간 로그인이 필요합니다.'){$('summaryCards').innerHTML=[card('메일 허브','mail.ekodi.kr','공통 서비스'),card('운영공간',workspaceLabel(),'tenant-local authority')].join('');$('mainPanel').innerHTML=`<h2>메일 관리 로그인</h2><p class="empty">${message}</p><div class="actions"><a class="button primary" href="${authUrl()}">Google 계정으로 계속</a><a class="button" href="https://mail.ekodi.kr/">Mail Hub 열기</a></div>`;state('로그인 필요')}
  function mailDnsLabel(domain,dns){if(dns?.routingDnsReady)return['수신 DNS 준비','live'];if(dns?.hasMx)return['다른 MX 사용 중','warn'];return['MX 연결 대기','warn']}
  async function mailAdmin(){try{await exchangeCentralToken();if(!(await accessToken()))return loginMailPanel();state('확인 중');const data=await mailApi('/workspace?slug='+encodeURIComponent(workspace));const domain=data.domains?.[0]||null;const dns=domain?data.dns?.[domain.hostname]:null;const [dnsLabel,dnsClass]=domain?mailDnsLabel(domain,dns):['도메인 미등록','warn'];const plan=domain?data.dnsPlans?.[domain.hostname]:null;$('summaryCards').innerHTML=[card('메일 도메인',domain?.hostname||'미등록',domain?.routingProvider||'routing provider'),card('수신 전달',domain?.defaultDestination||'미설정',domain?.deliveryMode||''),card('DNS',dnsLabel,dns?.nameservers?.join(', ')||'확인 전'),card('발신',domain?.outboundStatus==='ready'?'준비됨':'미설정',domain?.outboundProvider||'독립 SMTP/API 필요')].join('');const routes=(data.routes||[]).map(r=>`<tr><td><strong>${r.address}</strong></td><td>${r.destinationEmail}</td><td><span class="tag ${r.enabled?'live':'warn'}">${r.enabled?'수신':'중지'}</span></td><td>${r.sendEnabled?'발신 가능':'발신 미설정'}</td></tr>`).join('');const domainBlock=domain?`<div class="service-row"><div><strong>${domain.hostname}</strong><p>수신: ${domain.routingProvider} · 전달: ${domain.defaultDestination}</p><p>NS: ${(dns?.nameservers||[]).join(', ')||'확인되지 않음'}<br>MX: ${(dns?.mx||[]).join(', ')||'없음'}</p></div><span class="tag ${dnsClass}">${dnsLabel}</span></div>`:'';const canManage=Boolean(data.workspace?.canManage);$('mainPanel').innerHTML=`<h2>도메인 메일</h2><div class="service-list">${domainBlock}</div><h2 style="margin-top:18px">메일 주소</h2>${routes?`<div class="table-wrap"><table><thead><tr><th>주소</th><th>전달 받을 메일</th><th>수신</th><th>발신</th></tr></thead><tbody>${routes}</tbody></table></div>`:'<p class="empty">등록된 주소가 없습니다.</p>'}<div class="actions"><a class="button" href="https://mail.ekodi.kr/">Mail Hub 열기</a>${domain&&canManage?'<button class="button" id="verifyMailDns" type="button">DNS 다시 확인</button>':''}</div>${canManage&&domain?`<form id="mailRouteForm" class="actions" style="margin-top:18px"><input id="mailLocalPart" required placeholder="주소 예: info" style="min-width:180px;padding:8px 10px;border:1px solid #dce3ee;border-radius:8px"><input id="mailDestination" required type="email" value="${domain.defaultDestination||''}" placeholder="전달 받을 Gmail" style="min-width:260px;padding:8px 10px;border:1px solid #dce3ee;border-radius:8px"><button class="button primary" type="submit">주소 추가</button></form>`:''}<h2 style="margin-top:18px">필요 DNS 레코드</h2>${plan?.records?.length?`<div class="table-wrap"><table><thead><tr><th>유형</th><th>이름</th><th>우선순위</th><th>값</th></tr></thead><tbody>${plan.records.map(r=>`<tr><td>${r.type}</td><td>${r.name}</td><td>${r.priority??'-'}</td><td>${r.value}</td></tr>`).join('')}</tbody></table></div>`:'<p class="empty">선택한 수신 제공자의 DNS 계획이 없습니다.</p>'}${plan?.destinationVisibleInPublicDns?'<p class="empty">무료 Forward Email 방식은 전달 대상 주소가 DNS TXT에 공개됩니다. 민감한 개인 주소 대신 기관용 Gmail을 사용하는 이유입니다.</p>':''}<p class="empty" style="margin-top:16px">수신 전달과 발신 인증은 분리 관리합니다. DNS와 발신 인증이 실제로 확인되기 전에는 준비 완료로 표시하지 않습니다.</p>`;if(domain&&canManage&&$('verifyMailDns'))$('verifyMailDns').onclick=async()=>{state('DNS 확인 중');try{await mailApi('/verify',{method:'POST',body:JSON.stringify({workspace,domainId:domain.id})});await mailAdmin()}catch(e){state('확인 필요');$('pageCopy').textContent=e.message}};if(domain&&canManage&&$('mailRouteForm'))$('mailRouteForm').onsubmit=async e=>{e.preventDefault();state('저장 중');try{await mailApi('/routes',{method:'POST',body:JSON.stringify({workspace,domainId:domain.id,localPart:$('mailLocalPart').value,destinationEmail:$('mailDestination').value})});await mailAdmin()}catch(err){state('확인 필요');$('pageCopy').textContent=err.message}};state(data.workspace?.canManage?'관리 가능':'조회 전용')}catch(e){if(e.code==='AUTH_REQUIRED'||e.status===401)return loginMailPanel();$('summaryCards').innerHTML=[card('메일','확인 필요','실패를 성공으로 표시하지 않음')].join('');$('mainPanel').innerHTML=`<h2>메일 관리</h2><p class="empty">${e.message}</p><div class="actions"><a class="button" href="https://mail.ekodi.kr/">Mail Hub 열기</a></div>`;state('확인 필요')}}

  function automationQuery(){return '?subject_type=workspace&subject_key='+encodeURIComponent(canonicalSubjectKey())}
  function automationAuthUrl(){const u=new URL(AUTH_URL);u.searchParams.set('site','marketing');u.searchParams.set('return_to',location.href);return u.href}
  async function automationApi(path,options={}){const token=await accessToken();if(!token)throw Object.assign(new Error('AUTH_REQUIRED'),{code:'AUTH_REQUIRED'});const join=path.includes('?')?'&':'?';const r=await fetch(CHANNEL_AUTOMATION+path+join+automationQuery().slice(1),{...options,headers:{'content-type':'application/json',authorization:`Bearer ${token}`,...(options.headers||{})},cache:'no-store'});const d=await r.json().catch(()=>({}));if(!r.ok)throw Object.assign(new Error(d.error||`HTTP_${r.status}`),{code:d.error||'CHANNEL_ERROR',status:r.status,data:d});return d}
  function automationLogin(){ $('summaryCards').innerHTML=[card('쇼츠 자동화','로그인 필요','workspace 권한 확인'),card('채널','분리','다른 workspace와 공유하지 않음')].join('');$('mainPanel').innerHTML=`<h2>쇼츠 게시 자동화</h2><p class="empty">이 운영공간을 관리할 권한으로 로그인해야 합니다.</p><div class="actions"><a class="button primary" href="${automationAuthUrl()}">Google 계정으로 계속</a></div>`;state('로그인 필요') }
  const ae=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  async function automationPanel(){
    try{await exchangeCentralToken();if(!(await accessToken()))return automationLogin();state('확인 중');
      const [snap,connections]=await Promise.all([automationApi('/v1/automation'),automationApi('/v1/oauth/connections')]);
      const e=snap.entitlement||connections.entitlement||{}, rows=connections.connections||[], profiles=snap.profiles||[];
      const active=rows.filter(r=>r.status==='active'), pending=rows.filter(r=>r.status==='selection_required'||r.status==='pending_oauth');
      $('summaryCards').innerHTML=[card('등급',String(e.plan||'FREE').toUpperCase(),e.label||''),card('연결 채널',String(active.length),e.maxChannels===0?'업그레이드 필요':'최대 '+e.maxChannels+'개'),card('예약게시',e.scheduled?'가능':'제한',e.repeating?'반복 가능':'단발/초안'),card('AI 자동운영',e.autonomous?'가능':'검토 필요',e.autonomous?'AUTO':'수동 승인')].join('');
      const channelRows=rows.map(r=>{const choices=(r.discoveredChannels||[]).map(ch=>'<button class="button" type="button" data-channel-select="'+ae(r.id)+'" data-channel-id="'+ae(ch.id)+'">'+ae(ch.title)+' 선택</button>').join(' ');const actions=r.status==='selection_required'?choices:(r.status==='active'?'<button class="button" type="button" data-channel-disconnect="'+ae(r.id)+'">연결 해제</button>':'');return '<div class="service-row"><div><strong>'+ae(r.displayName||'YouTube 연결')+'</strong><p>'+ae(r.provider)+' · '+ae(r.externalAccountId||r.status)+'</p><div class="actions">'+actions+'</div></div><span class="tag '+(r.status==='active'?'live':'warn')+'">'+ae(r.status)+'</span></div>'}).join('');
      const templates=(e.templates||[]).map(t=>'<span class="tag">'+ae(t.label)+'</span>').join(' ');
      $('mainPanel').innerHTML='<h2>쇼츠 게시 자동화</h2><p class="empty">이 공간의 채널과 자동화는 다른 개인·기관·단체 공간과 분리됩니다.</p><p class="empty">YouTube 연결 대상 계정: <strong>'+ae(channelTargetAccount('youtube')||'인증 시 Google 계정 선택')+'</strong></p><div class="service-list">'+(channelRows||'<p class="empty">연결된 채널이 없습니다.</p>')+'</div><div class="actions"><button class="button primary" id="connectYoutube" type="button" '+(Number(e.maxChannels||0)<1?'disabled':'')+'>'+(active.some(r=>r.provider==='youtube')?'YouTube 재인증':'YouTube 인증')+'</button><a class="button" href="https://marketing.ekodi.kr/">Marketing AI 열기</a></div><h2 style="margin-top:18px">사용 가능한 자동화</h2><p>'+templates+'</p><p class="empty">'+(profiles.length?'활성 프로필 '+profiles.filter(x=>x.enabled).length+'개':'아직 자동화 프로필이 없습니다.')+'</p>'+(pending.length?'<p class="empty">OAuth 완료 후 채널 선택이 필요한 연결이 '+pending.length+'개 있습니다.</p>':'');
      const btn=$('connectYoutube');if(btn)btn.onclick=async()=>{try{state('연결 준비');const r=await automationApi('/v1/oauth/youtube/start',{method:'POST',body:JSON.stringify({returnTo:location.href,accountHint:channelTargetAccount('youtube')})});location.assign(r.authorizeUrl)}catch(err){state('연결 필요');$('pageCopy').textContent=err.message}};
      document.querySelectorAll('[data-channel-select]').forEach(b=>b.onclick=async()=>{try{state('채널 연결 중');await automationApi('/v1/oauth/connections/'+encodeURIComponent(b.dataset.channelSelect)+'/select',{method:'POST',body:JSON.stringify({externalAccountId:b.dataset.channelId})});await automationPanel()}catch(err){state('연결 필요');$('pageCopy').textContent=err.message}});
      document.querySelectorAll('[data-channel-disconnect]').forEach(b=>b.onclick=async()=>{try{state('연결 해제 중');await automationApi('/v1/oauth/connections/'+encodeURIComponent(b.dataset.channelDisconnect)+'/disconnect',{method:'POST',body:'{}'});await automationPanel()}catch(err){state('확인 필요');$('pageCopy').textContent=err.message}});
      state('운영');
    }catch(e){if(e.code==='AUTH_REQUIRED'||e.status===401)return automationLogin();$('summaryCards').innerHTML=[card('쇼츠 자동화','확인 필요','실패를 성공으로 표시하지 않음')].join('');$('mainPanel').innerHTML='<h2>쇼츠 게시 자동화</h2><p class="empty">'+ae(e.message)+'</p>';state('확인 필요')}
  }

  async function mallGrowthControl(options={}){const token=await accessToken();if(!token)throw Object.assign(new Error('AUTH_REQUIRED'),{code:'AUTH_REQUIRED',status:401});const r=await fetch(`${base}/mall/api/growth/control`,{...options,headers:{'content-type':'application/json',authorization:`Bearer ${token}`,...(options.headers||{})},cache:'no-store'});const d=await r.json().catch(()=>({}));if(!r.ok)throw Object.assign(new Error(d.error||`growth_control_${r.status}`),{status:r.status,code:d.error});return d}
  async function mallGrowthInsights(){const token=await accessToken();if(!token)throw Object.assign(new Error('AUTH_REQUIRED'),{code:'AUTH_REQUIRED',status:401});const r=await fetch(`${base}/mall/api/growth/insights`,{headers:{authorization:`Bearer ${token}`},cache:'no-store'});const d=await r.json().catch(()=>({}));if(!r.ok)throw Object.assign(new Error(d.error||`growth_insights_${r.status}`),{status:r.status,code:d.error});return d}
  function platformAdminToken(){return platformAdminSessionToken}
  function markPlatformAdminIntent(){try{sessionStorage.setItem(PLATFORM_ADMIN_INTENT_KEY,String(Date.now()))}catch{}}
  function clearPlatformAdminIntent(){try{sessionStorage.removeItem(PLATFORM_ADMIN_INTENT_KEY)}catch{}}
  function hasPlatformAdminIntent(){try{const at=Number(sessionStorage.getItem(PLATFORM_ADMIN_INTENT_KEY)||0);if(!at||Date.now()-at>PLATFORM_ADMIN_INTENT_MAX_AGE_MS){clearPlatformAdminIntent();return false}return true}catch{return false}}
  function acceptPlatformAdminHandoff(){const p=new URLSearchParams(location.hash.slice(1)),value=p.get('ekodi_admin_token');if(!value)return false;platformAdminSessionToken=value;clearPlatformAdminIntent();history.replaceState(null,'',location.pathname+location.search);return true}
  function platformAdminAuthUrl(){const u=new URL(AUTH_URL);u.searchParams.set('site','admin');u.searchParams.set('direct','1');u.searchParams.set('return_to',location.origin+location.pathname+location.search);return u.href}
  async function affiliateApi(path,options={}){const token=platformAdminToken();if(!token)throw Object.assign(new Error('PLATFORM_ADMIN_AUTH_REQUIRED'),{code:'PLATFORM_ADMIN_AUTH_REQUIRED',status:401});const headers={'content-type':'application/json',authorization:`Bearer ${token}`,...(options.headers||{})};const r=await fetch(AFFILIATE_API+path,{...options,headers,cache:'no-store'});const d=await r.json().catch(()=>({}));if(r.status===401)platformAdminSessionToken='';if(!r.ok)throw Object.assign(new Error(d.error||`affiliate_${r.status}`),{status:r.status,code:d.code||d.error});return d}
  const AFFILIATE_APPLICATION={candidate:'후보',prepared:'가입 준비',account_exists:'계정보유',applied:'신청완료',review:'심사중',approved:'승인됨',active:'활성',blocked:'보류'};
