  function affiliateProgramRow(item){const key=ae(item.programKey||'');const contacted=item.lastOutreachAt?`${item.outreachChannel||'연락'} · ${new Date(item.lastOutreachAt).toLocaleDateString('ko-KR')}`:'연락 기록 없음';return `<div class="trade-scope-box" data-affiliate-program="${key}"><strong>${ae(item.programName||item.programKey)}</strong><p class="empty">${ae(item.coverageSummary||item.region||'')} · 준비도 ${Number(item.readinessScore||0)}% · ${ae(contacted)}</p><div class="actions"><select data-affiliate-application>${affiliateOptions(AFFILIATE_APPLICATION,item.applicationStatus)}</select><select data-affiliate-integration>${affiliateOptions(AFFILIATE_INTEGRATION,item.integrationStatus)}</select><select data-affiliate-outreach>${affiliateOptions(AFFILIATE_OUTREACH,item.outreachStatus||'none')} </select>${item.programUrl?`<a class="button" href="${ae(item.programUrl)}" target="_blank" rel="noopener">공식 관리 ↗</a>`:''}<button class="button primary" type="button" data-affiliate-program-save="${key}">상태 저장</button></div></div>`}
