  function bindAffiliateAdmin(kind){const root=document.querySelector('[data-affiliate-admin-console]');if(!root)return;root.addEventListener('click',async event=>{const save=event.target.closest('[data-affiliate-program-save]'),provider=event.target.closest('[data-affiliate-provider-sync]'),action=event.target.closest('[data-affiliate-action]');if(!save&&!provider&&!action)return;const button=save||provider||action,message=root.querySelector('[data-affiliate-console-message]');button.disabled=true;try{if(save){const row=save.closest('[data-affiliate-program]'),key=row?.dataset.affiliateProgram||'';await affiliateApi('/programs/'+encodeURIComponent(key),{method:'PUT',body:JSON.stringify({applicationStatus:row.querySelector('[data-affiliate-application]')?.value,integrationStatus:row.querySelector('[data-affiliate-integration]')?.value,outreachStatus:row.querySelector('[data-affiliate-outreach]')?.value})});if(message)message.textContent=key+' 상태 저장 완료'}else if(provider){const key=provider.dataset.affiliateProviderSync||'';await affiliateApi('/providers/'+encodeURIComponent(key)+'/sync',{method:'POST',body:'{}'});if(message)message.textContent=key+' Feed 동기화 완료'}else if(action?.dataset.affiliateAction==='automation'){await affiliateApi('/automation/run',{method:'POST',body:'{}'});if(message)message.textContent='쿠팡 상품 자동수집 실행 완료'}else if(action?.dataset.affiliateAction==='reporting'){await affiliateApi('/reporting/sync',{method:'POST',body:'{}'});if(message)message.textContent='쿠팡 실적 동기화 완료'}await growthPolicyPanel(kind)}catch(err){if(message)message.textContent=err.message;state('제휴관리 확인 필요')}finally{button.disabled=false}})}
  async function growthPolicyPanel(kind){
    try{await exchangeCentralToken();if(!(await accessToken()))return loginPanel('영업 자동화 설정에는 운영공간 로그인이 필요합니다.');state('정책 확인 중');const data=await mallGrowthControl();const p=data.policy||{},sources=p.sources||[],channels=p.channels||[],learning=p.learning||{},autonomy=p.autonomy||{};let affiliate=null;if(kind==='sourcing'&&platformAdminToken()){try{affiliate=await affiliateAdminSnapshot()}catch(e){if(e.status!==401)throw e}}$('summaryCards').innerHTML=[card('자율운영',autonomy.enabled?'ON':'OFF',autonomy.approvalMode||'guarded'),card('활성 소싱처',String(sources.filter(x=>x.enabled).length),sources.length+'개 중'),card('자동게시 대상',String(channels.filter(x=>x.enabled).length),channels.length+'개 채널'),card('정책',p.version||'v8.1','성과학습')].join('');
      if(kind==='sourcing'){$('mainPanel').innerHTML=`<h2>판매·공급망 관리</h2><p class="empty">공통 판매·공급망 엔진을 사용하되, 이 쇼핑몰이 실제로 사용할 공급처·제휴처와 적용 여부는 이 운영공간이 결정합니다. 추천 적합성은 수수료와 분리됩니다.</p>${affiliate?affiliateAdminConsole(affiliate):affiliateAdminLocked()}<h2 style="margin-top:18px">이 몰에서 실제 사용할 판매처</h2><form id="growthControlForm"><div class="service-list">${sources.map(x=>controlToggle('source:'+x.id,x.label,x.enabled,(x.kind||'source')+' · '+(x.enabled?'적용':'중지'))).join('')}</div><div class="actions"><button class="button primary" type="submit">판매·공급망 설정 저장</button></div></form>`;bindAffiliateAdmin(kind)}
      else{$('mainPanel').innerHTML=`<h2>8세대 자율 영업루프</h2><p class="empty">적합 상품만 대상으로 게시 → 유입 → 전환 → 수익을 학습하고 다음 배포 비중을 조정합니다.</p><form id="growthControlForm">${controlToggle('autonomy','자율 영업루프',Boolean(autonomy.enabled),'가드레일 안에서 자동 순환')}<div class="service-list">${channels.map(x=>`<div class="service-row"><div><strong>${ae(x.label)}</strong><p>하루 최대 ${Number(x.maxPostsPerDay||0)}회 · 최소 ${Number(x.minHoursBetweenPosts||0)}시간 간격</p></div><input type="checkbox" name="channel:${ae(x.id)}" ${x.enabled?'checked':''}></div>`).join('')}</div><div class="actions"><label>탐색 비중 <input name="exploration" type="number" min="5" max="50" value="${Math.round(Number(learning.explorationShare||0.2)*100)}">%</label><label>손실 정지선 <input name="stopLoss" type="number" min="0" step="1000" value="${Number(learning.stopLossKrw||5000)}">원</label><label>피드백 최소 표본 <input name="feedbackSample" type="number" min="3" max="100" value="${Number(learning.minFeedbackSample||10)}">건</label><label>부정 피드백 정지선 <input name="negativeFeedbackRate" type="number" min="5" max="90" value="${Math.round(Number(learning.maxNegativeFeedbackRate||0.35)*100)}">%</label><button class="button primary" type="submit">영업루프 저장</button></div></form>`}
      const form=$('growthControlForm');form.onsubmit=async e=>{e.preventDefault();state('저장 중');const fd=new FormData(form),next=JSON.parse(JSON.stringify(p));if(kind==='sourcing')next.sources=(next.sources||[]).map(x=>({...x,enabled:fd.has('source:'+x.id)}));else{next.autonomy={...(next.autonomy||{}),enabled:fd.has('autonomy')};next.channels=(next.channels||[]).map(x=>({...x,enabled:fd.has('channel:'+x.id)}));next.learning={...(next.learning||{}),explorationShare:Number(fd.get('exploration')||20)/100,stopLossKrw:Number(fd.get('stopLoss')||5000),minFeedbackSample:Number(fd.get('feedbackSample')||10),maxNegativeFeedbackRate:Number(fd.get('negativeFeedbackRate')||35)/100}};await mallGrowthControl({method:'PUT',body:JSON.stringify({policy:next})});state('저장됨');await growthPolicyPanel(kind)};state(data.authority==='tenant'?'운영공간 권한':'관리자 권한')}catch(e){if(e.code==='AUTH_REQUIRED'||e.status===401)return loginPanel();$('summaryCards').innerHTML=[card('영업루프','확인 필요','실패를 성공으로 표시하지 않음')].join('');$('mainPanel').innerHTML=`<h2>영업 자동화 설정</h2><p class="empty">${ae(e.message)}</p>`;state('확인 필요')}}
﻿  const mallActionLabel=Object.freeze({scale:'확대',test:'실험',observe:'관찰',hold:'보류'});
